VALUES ('club_cleveland-mayfield-village-community-center', 'Mayfield Village Community Center', 'cleveland-mayfield-village-community-center', 'Mayfield Village Senior Services runs Mah Jongg on Mondays and Beginner Mah Jongg Lessons (instructor Fern Grunburger). Lesson page: "National Mah Jongg League 2026 Card (hands and rules)" and "American Mah Jongg is attracting a whole new generation of players who love its unique blend of strategy, pattern recognition, and a little bit of luck." Lessons Thursdays 12:30-2:30 PM; $50 per session; register one week ahead. Venue is Mayfield Village (Community Room / Civic Center).', (SELECT id FROM City WHERE name = 'Cleveland' AND state = 'OH'), '6622 Wilson Mills Road, Mayfield Village, OH', 'https://recreation.mayfieldvillage.com/senior-services/', NULL, NULL, NULL, NULL, 1, 1, 0, 1, 0, 0, NULL, 'Mah Jongg Mondays (time not stated); beginner lessons Thursdays 12:30-2:30 PM in 8 sessions Sept 2026-May 2027', 'https://recreation.mayfieldvillage.com/programs/beginner-mah-jongg-lessons/', '2026-11-19', 'ACTIVE')
